  9: /** Run with Java 25: java ci/TestVerifyTestReports.java. Fixtures never launch Maven or a browser. */
 10: public class TestVerifyTestReports {
 11:     private static final String GOOD = suite("2", "0", "0", "1",
 12:             "<testcase name=\"pass\"/><testcase name=\"skip\"><skipped/></testcase>");
 13:     private static final String SKIPPED = suite("1", "0", "0", "1",
 14:             "<testcase name=\"skip\"><skipped/></testcase>");
 15:     private static final String SUMMARY = """
 16:             <failsafe-summary result="null" timeout="false">
 17:               <completed>2</completed><errors>0</errors><failures>0</failures><skipped>1</skipped>
 18:               <flakes>0</flakes><failureMessage/>
 19:             </failsafe-summary>
 20:             """;
 21:     private static int passed;
 22: 
 23:     public static void main(String[] args) throws Exception {
 24:         check("standard passes without Failsafe", "standard", true, root -> standard(root, GOOD));
 25:         check("integration passes with matching summary", "integration", true, TestVerifyTestReports::integration);
 26:         check("missing directory", "standard", false, root -> {});
 27:         check("missing TEST XML", "standard", false,
 28:                 root -> write(root, "target/surefire-reports/ordinary.txt", "not evidence"));
 29:         check("empty XML", "standard", false, root -> standard(root, ""));
 30:         check("corrupt XML", "standard", false, root -> standard(root, "<testsuite><sensitive-unclosed>"));
 31:         check("wrong root", "standard", false, root -> standard(root, "<testsuites/>"));
 32:         check("failed testcase", "standard", false, root -> standard(root,
 33:                 suite("1", "1", "0", "0", "<testcase><failure>DO_NOT_LOG_PAYLOAD</failure></testcase>")));
 34:         check("errored testcase", "standard", false, root -> standard(root,
 35:                 suite("1", "0", "1", "0", "<testcase><error/></testcase>")));
 36:         check("all tests skipped", "standard", false, root -> standard(root, SKIPPED));
 37:         check("zero tests", "standard", false, root -> standard(root, suite("0", "0", "0", "0", "")));
 38:         check("fabricated test count", "standard", false, root -> standard(root,
 39:                 suite("1", "0", "0", "0", "")));
 40:         check("failure hidden by counters", "standard", false, root -> standard(root,
 41:                 suite("1", "0", "0", "0", "<testcase><failure/></testcase>")));
 42:         check("invalid negative counter", "standard", false, root -> standard(root,
 43:                 suite("-1", "0", "0", "0", "")));
 44:         check("missing counter", "standard", false, root -> standard(root, GOOD.replace(" skipped=\"1\"", "")));
 45:         check("corrupt XML among good reports", "standard", false, root -> {
 46:             standard(root, GOOD);
 47:             write(root, "target/surefire-reports/TEST-corrupt.xml", "broken");
 48:         });
 49:         check("DOCTYPE and external entities forbidden", "standard", false, root -> standard(root,
 50:                 "<!DOCTYPE testsuite [<!ENTITY leak SYSTEM \"file:///DO_NOT_LOG_PAYLOAD\">]>" + GOOD));
 51:         check("integration missing Failsafe", "integration", false, root -> standard(root, GOOD));
 52:         check("summary alone is insufficient", "integration", false, root -> {
 53:             standard(root, GOOD);
 54:             write(root, "target/failsafe-reports/failsafe-summary.xml", SUMMARY);
 55:         });
 56:         check("integration missing Surefire", "integration", false, root -> {
 57:             write(root, "target/failsafe-reports/TEST-fixture.xml", GOOD);
 58:             write(root, "target/failsafe-reports/failsafe-summary.xml", SUMMARY);
 59:         });
 60:         check("integration missing summary", "integration", false, root -> {
 61:             standard(root, GOOD);
 62:             write(root, "target/failsafe-reports/TEST-fixture.xml", GOOD);
 63:         });
 64:         check("integration entirely skipped", "integration", false, root -> {
 65:             integration(root);
 66:             write(root, "target/failsafe-reports/TEST-fixture.xml", SKIPPED);
 67:         });
 68:         check("integration failed exit result", "integration", false, root -> {
 69:             integration(root);
 70:             write(root, "target/failsafe-reports/failsafe-summary.xml", SUMMARY.replace("result=\"null\"", "result=\"255\""));
 71:         });
 72:         check("integration timeout", "integration", false, root -> {
 73:             integration(root);
 74:             write(root, "target/failsafe-reports/failsafe-summary.xml", SUMMARY.replace("timeout=\"false\"", "timeout=\"true\""));
 75:         });
 76:         check("integration summary mismatch", "integration", false, root -> {
 77:             integration(root);
 78:             write(root, "target/failsafe-reports/failsafe-summary.xml", SUMMARY.replace("<completed>2", "<completed>3"));
 79:         });
 80:         check("integration fork failure message", "integration", false, root -> {
 81:             integration(root);
 82:             write(root, "target/failsafe-reports/failsafe-summary.xml",
 83:                     SUMMARY.replace("<failureMessage/>", "<failureMessage>DO_NOT_LOG_PAYLOAD</failureMessage>"));
 84:         });
 85:         System.out.println("Required report guard fixtures: PASS (" + passed + " cases)");
 86:     }
