 88:     private static void check(String name, String mode, boolean expected, Consumer<Path> setup) throws Exception {
 89:         Path root = Files.createTempDirectory("lab-report-fixture-");
 90:         try {
 91:             setup.accept(root);
 92:             var output = new ByteArrayOutputStream();
 93:             int status;
 94:             try (var stream = new PrintStream(output, true, StandardCharsets.UTF_8)) {
 95:                 status = VerifyTestReports.run(new String[] {mode, "--root", root.toString()}, stream, stream);
 96:             }
 97:             String text = output.toString(StandardCharsets.UTF_8);
 98:             if ((status == 0) != expected || text.contains("DO_NOT_LOG_PAYLOAD") || text.contains("sensitive-unclosed")) {
 99:                 throw new AssertionError("Fixture failed: " + name + "; exit=" + status);
100:             }
101:             if (expected && (!text.contains("executed=1") || !text.contains("Required test reports: PASS"))) {
102:                 throw new AssertionError("Missing successful validation counts: " + name);
103:             }
104:             if (!expected && !text.contains("Required test reports: FAIL")) {
105:                 throw new AssertionError("Missing failure verdict: " + name);
106:             }
107:             passed++;
108:         } finally {
109:             // Only this exact, freshly created fixture directory is removed.
110:             try (var files = Files.walk(root)) {
111:                 for (Path file : files.sorted(Comparator.reverseOrder()).toList()) {
112:                     Files.delete(file);
113:                 }
114:             }
115:         }
116:     }
117: 
118:     private static String suite(String tests, String failures, String errors, String skipped, String cases) {
119:         return "<testsuite tests=\"" + tests + "\" failures=\"" + failures + "\" errors=\"" + errors
120:                 + "\" skipped=\"" + skipped + "\">" + cases + "</testsuite>";
121:     }
122: 
123:     private static void standard(Path root, String content) {
124:         write(root, "target/surefire-reports/TEST-fixture.xml", content);
125:     }
126: 
127:     private static void integration(Path root) {
128:         standard(root, GOOD);
129:         write(root, "target/failsafe-reports/TEST-fixture.xml", GOOD);
130:         write(root, "target/failsafe-reports/failsafe-summary.xml", SUMMARY);
131:     }
132: 
133:     private static void write(Path root, String relative, String content) {
134:         try {
135:             Path file = root.resolve(relative);
136:             Files.createDirectories(file.getParent());
137:             Files.writeString(file, content, StandardCharsets.UTF_8);
138:         } catch (Exception e) {
139:             throw new IllegalStateException("Unable to create report fixture", e);
140:         }
141:     }
142: }
